import{_ as e,o as s,c as i,a0 as t}from"./chunks/framework.DCluYYrN.js";const k=JSON.parse('{"title":"Module WebUI","description":"","frontmatter":{},"headers":[],"relativePath":"ja_JP/guide/module-webui.md","filePath":"ja_JP/guide/module-webui.md"}'),n={name:"ja_JP/guide/module-webui.md"};function p(l,a,r,o,h,d){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="module-webui" tabindex="-1">Module WebUI <a class="header-anchor" href="#module-webui" aria-label="Permalink to &quot;Module WebUI&quot;">​</a></h1><p>KernelSU のモジュールは、ブートスクリプトの実行やシステムファイルの修正に加えて、UI インターフェースの表示やユーザーとの対話もサポートしています。</p><p>モジュールは、任意の Web 技術を通じて HTML + CSS + JavaScript のページを作成することができます。KernelSU のマネージャーは WebView を通じてこれらのページを表示します。また、シェルコマンドの実行など、システムと対話するためのいくつかのAPIを提供しています。</p><h2 id="webroot-ディレクトリ" tabindex="-1"><code>webroot</code> ディレクトリ <a class="header-anchor" href="#webroot-ディレクトリ" aria-label="Permalink to &quot;\`webroot\` ディレクトリ&quot;">​</a></h2><p>Web リソースファイルは、モジュールのルートディレクトリの <code>webroot</code> サブディレクトリに置かれるべきであり、<code>index.html</code> という名前のファイルが必ず存在しなければなりません。これがモジュールページのエントリです。Web インターフェイスを含む最もシンプルなモジュール構造は以下の通りです：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❯ tree .</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>|-- module.prop</span></span>
<span class="line"><span>\`-- webroot</span></span>
<span class="line"><span>    \`-- index.html</span></span></code></pre></div><p>:::警告 モジュールをインストールするとき、KernelSU はこのディレクトリのパーミッションと SELinux コンテキストを自動的に設定します。何をしているかわからないのであれば、自分でこのディレクトリのパーミッションを設定しないでください！ :::</p><p>ページに css や JavaScript が含まれている場合は、このディレクトリに配置する必要があります。</p><h2 id="javascript-api" tabindex="-1">JavaScript API <a class="header-anchor" href="#javascript-api" aria-label="Permalink to &quot;JavaScript API&quot;">​</a></h2><p>単なる表示ページであれば、通常の Web ページとの違いはありません。より重要なのは、KernelSU がモジュールの固有機能を実装させるための一連のシステム API を提供することです。</p><p>KernelSU は JavaScript ライブラリを提供し、<a href="https://www.npmjs.com/package/kernelsu" target="_blank" rel="noreferrer">npm で公開しています</a>。これを Web ページの JavaScript コードで使用することができます。</p><p>たとえば、特定の設定を取得したり、プロパティを変更するために、シェルコマンドを実行することができます：</p><div class="language-JavaScript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">JavaScript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { exec } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;kernelsu&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">errno</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">stdout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> exec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;getprop ro.product.model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>別の例として、Webページをフルスクリーンで表示したり、トーストを表示することができます。</p><p><a href="https://www.npmjs.com/package/kernelsu" target="_blank" rel="noreferrer">API ドキュメント</a></p><p>既存のAPIがご自身のニーズを満たしていない、または使い勝手が不便である場合、<a href="https://github.com/tiann/KernelSU/issues" target="_blank" rel="noreferrer">こちら</a>でご提案いただければ幸いです！</p><h2 id="いくつかのヒント" tabindex="-1">いくつかのヒント <a class="header-anchor" href="#いくつかのヒント" aria-label="Permalink to &quot;いくつかのヒント&quot;">​</a></h2><ol><li><code>localStorage</code> を通常通りに使用してデータを保存することができますが、Manager アプリをアンインストールした後には失われます。永続的に保存する必要がある場合は、自分でいくつかのディレクトリにデータを書き込むことができます。</li><li>シンプルなページには、<a href="https://parceljs.org/" target="_blank" rel="noreferrer">parceljs</a>を使用することをお勧めします。設定が不要で非常に便利です。しかし、フロントエンドの達人である場合や、自分の好みがある場合は、気に入ったものを選んでください！</li></ol>`,18)])])}const u=e(n,[["render",p]]);export{k as __pageData,u as default};
